  <style>
    .vc-header-logo {
    display: -webkit-flex;
    display: flex;
    -webkit-align-items: center;
    gap: 12px;
    justify-content: space-between;
    align-items: center;
}
   /* Container tombol */
   .n-columns-2 {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 15px;
    font-weight: 700;
    margin: 0 auto;
   }

   .n-columns-2 a {
    text-align: center;
    margin: 0;
    text-decoration: none;
    transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    position: relative;
    overflow: hidden;
   }

   .login,
   .register {
    color: #ffffff;
    padding: 16px 10px;
    letter-spacing: 1px;
    font-size: 18px;
    text-transform: uppercase;
   }

   /* Efek kilau untuk kedua tombol */
   .login::after,
   .register::after {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: linear-gradient(
        135deg,
        rgba(255, 255, 255, 0) 0%,
        rgba(255, 255, 255, 0.2) 25%,
        rgba(255, 255, 255, 0) 50%
    );
    transform: translateX(-100%) translateY(-100%) rotate(45deg);
    transition: transform 0.6s ease;
    pointer-events: none;
   }

   .login:hover::after,
   .register:hover::after {
    transform: translateX(100%) translateY(100%) rotate(45deg);
   }

   /* Tombol LOGIN - Modern Blue Glossy Premium */
   .login,
   .login-button {
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
    border-radius: 12px;
    border: 2px solid rgb(11, 18, 32);
    box-shadow: 
        0 4px 0 #38BDF8,
        0 8px 15px rgba(0, 0, 0, 0.3),
        inset 0 1px 2px rgba(255, 255, 255, 0.5);
    background: linear-gradient(180deg, 
        #38BDF8 0%,
        #38BDF8 30%,
        #38BDF8 70%,
        #38BDF8 100%);
    color: #fff;
    position: relative;
   }

   /* Efek highlight atas untuk efek chrome */
   .login::before {
    content: '';
    position: absolute;
    top: 2px;
    left: 5%;
    width: 90%;
    height: 30%;
    background: linear-gradient(180deg, 
        rgba(255, 255, 255, 0.6) 0%,
        rgba(255, 255, 255, 0.2) 50%,
        rgba(255, 255, 255, 0) 100%);
    border-radius: 10px 10px 0 0;
    pointer-events: none;
   }

   .login:hover {
    background: linear-gradient(180deg, 
        #7DD3FC 0%,
        #38BDF8 30%,
        #38BDF8 70%,
        #0EA5E9 100%);
    border-color: rgba(56, 189, 248, 0.6);
    box-shadow: 
        0 6px 0 #0369A1,
        0 12px 20px rgba(0, 0, 0, 0.4),
        inset 0 1px 3px rgba(255, 255, 255, 0.8);
    transform: translateY(-2px);
    color: white;
   }

   .login:active {
    transform: translateY(2px);
    box-shadow: 
        0 2px 0 #0369A1,
        0 5px 12px rgba(0, 0, 0, 0.3);
   }

   /* Tombol REGISTER - Dark Blue Premium */
   .register,
   .register-button {
    text-shadow: 2px 2px 4px rgba(56, 189, 248, 0.6);
    border-radius: 12px;
    border: 2px solid rgba(56, 189, 248, 0.6);
    box-shadow: 
        0 4px 0 #38BDF8,
        0 8px 15px rgba(56, 189, 248, 0.6),
        inset 0 1px 2px rgba(255, 255, 255, 0.3);
    background: linear-gradient(180deg, 
        #38BDF8 0%,
        #38BDF8 30%,
        #38BDF8 70%,
        #38BDF8 100%);
    color: #fff;
    position: relative;
   }

   /* Efek highlight atas untuk efek dark chrome */
   .register::before {
    content: '';
    position: absolute;
    top: 2px;
    left: 5%;
    width: 90%;
    height: 30%;
    background: linear-gradient(180deg, 
        rgba(255, 255, 255, 0.4) 0%,
        rgba(255, 255, 255, 0.1) 50%,
        rgba(255, 255, 255, 0) 100%);
    border-radius: 10px 10px 0 0;
    pointer-events: none;
   }

   .register:hover {
    background: linear-gradient(180deg, 
        #475569 0%,
        #334155 30%,
        #1E293B 70%,
        #0F172A 100%);
    border-color: rgba(255, 255, 255, 0.2);
    box-shadow: 
        0 6px 0 #38BDF8,
        0 12px 20px rgba(0, 0, 0, 0.5),
        inset 0 1px 3px rgba(255, 255, 255, 0.4);
    transform: translateY(-2px);
    color: #38BDF8;
   }

   .register:active {
    transform: translateY(2px);
    box-shadow: 
        0 2px 0 #38BDF8,
        0 5px 12px rgba(0, 0, 0, 0.3);
   }

   /* Efek hover untuk interaksi */
   .login:hover, .register:hover {
    opacity: 1;
    filter: brightness(1.1);
   }

   /* Efek ikon panah kecil (opsional) */
   .login span, .register span {
    display: inline-block;
    transition: transform 0.3s ease;
   }

   .login:hover span, .register:hover span {
    transform: translateX(5px);
   }

   /* Responsif untuk mobile */
   @media (max-width: 480px) {
    .n-columns-2 {
        gap: 10px;
    }
    
    .login, .register {
        padding: 14px 8px;
        font-size: 16px;
    }
   }
</style>
