				--transition-smooth: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
			}

			/* === MAIN CONTAINER (Neumorphic Base) === */
			.info-box-gg {
				max-width: 900px;
				margin: 20px auto;
				background: linear-gradient(165deg, #0F1A2B 0%, #0B1220 100%);
				border-radius: 24px;
				border: 1px solid rgba(56, 189, 248, 0.37);
				box-shadow: 
					15px 15px 35px var(--shadow-dark),
					-10px -10px 25px rgba(255, 255, 255, 0.02),
					inset 0 0 15px rgba(56, 189, 248, 0.08);
				overflow: hidden;
				font-family: 'Poppins', sans-serif;
				position: relative;
				padding: 6px;
			}

			/* Glow Accent Filter Overlay */
			.info-box-gg::before {
				content: '';
				position: absolute;
				top: 0;
				left: 0;
				right: 0;
				bottom: 0;
				background: radial-gradient(circle at 50% 0%, rgba(56, 189, 248, 0.12), transparent 70%);
				pointer-events: none;
				z-index: 0;
			}

			/* === HEADER (High-Gloss Metallic Blue) === */
			.info-header-gg {
				background: linear-gradient(180deg, #ffffff 0%, #BAE6FD 20%, #0EA5E9 60%, #0284C7 100%);
				color: #0B1220;
				text-align: center;
				padding: 18px 20px;
				font-size: 16px;
				font-weight: 800;
				letter-spacing: 1.5px;
				border-radius: 18px 18px 12px 12px;
				position: relative;
				z-index: 1;
				text-transform: uppercase;
				text-shadow: 0 1px 0 rgba(255, 255, 255, 0.5);
				box-shadow: 
					0 6px 20px rgba(0, 0, 0, 0.8),
					inset 0 2px 1px rgba(255, 255, 255, 0.9),
					inset 0 -2px 4px rgba(0, 0, 0, 0.4);
			}

			.info-header-gg::after {
				content: '✦';
				position: absolute;
				right: 25px;
				top: 50%;
				transform: translateY(-50%);
				color: #0B1220;
				font-size: 18px;
			}

			/* === ROWS (Inset Neumorphic Panels) === */
			.info-row-gg {
				display: flex;
				justify-content: space-between;
				align-items: center;
				padding: 12px 20px;
				margin: 8px 6px;
				border-radius: 14px;
				background: #0E1826;
				border: 1px solid rgba(56, 189, 248, 0.15);
				box-shadow: 
					inset 3px 3px 6px #060B14, 
					inset -3px -3px 6px #16233A;
				position: relative;
				z-index: 1;
				transition: var(--transition-smooth);
			}

			.info-row-gg:hover {
				border-color: rgba(56, 189, 248, 0.4);
				box-shadow: 
					inset 1px 1px 3px #060B14, 
					inset -1px -1px 3px #16233A,
					0 0 12px rgba(56, 189, 248, 0.15);
				transform: translateY(-1px);
			}

			/* === LABEL === */
			.info-label-gg {
				font-weight: 600;
				color: var(--text-muted);
				width: 35%;
				font-size: 12px;
				letter-spacing: 0.5px;
				position: relative;
				padding-left: 18px;
			}

			/* Sparkle Emas di Depan Label */
			.info-label-gg::before {
				content: '◆';
				position: absolute;
				left: 0;
				top: 50%;
				transform: translateY(-50%);
				color: var(--accent-primary);
				font-size: 8px;
				filter: drop-shadow(0 0 4px var(--accent-primary));
			}

			/* === VALUE === */
			.info-value-gg {
				font-weight: 600;
				color: var(--text-light);
				width: 65%;
				font-size: 12px;
				line-height: 1.5;
				text-align: right;
			}

			/* High-Gloss Blue Tag pada Value Strong */
			.info-value-gg strong {
				background: linear-gradient(180deg, #BAE6FD 0%, #0EA5E9 100%);
				color: #0B1220;
				font-weight: 800;
				padding: 4px 12px;
				border-radius: 50px;
				margin-left: 5px;
				font-size: 11px;
				box-shadow: 
					0 3px 8px rgba(0,0,0,0.6), 
					inset 0 1px 0 rgba(255,255,255,0.8);
				border: 1px solid #7DD3FC;
				display: inline-block;
			}

			/* === RATING SPECIAL === */
			.rating-gg {
				display: flex;
				align-items: center;
				justify-content: flex-end;
				gap: 8px;
				flex-wrap: wrap;
			}

			.rating-gg::before {
				content: '★★★★★';
				background: linear-gradient(180deg, #ffffff 0%, #38BDF8 100%);
				-webkit-background-clip: text;
				-webkit-text-fill-color: transparent;
				letter-spacing: 2px;
				font-size: 15px;
				filter: drop-shadow(0 2px 4px rgba(0,0,0,0.8));
			}

			/* === RESPONSIVE DESIGN === */
			@media (max-width: 600px) {
				.info-row-gg {
