         <style>
   :root {
    /* Mengubah palet abu-abu menjadi Modern Blue */
    --brand: #38BDF8;      /* Blue/Chrome Light */
    --brand-mid: #38BDF8;  /* Chrome Standard */
    --brand-dark: #38BDF8; /* Chrome Deep */
    --border: #1E3A8A;
    --bg: #ffffff;
    --shadow: 0 6px 15px rgba(0, 0, 0, .08);
   }

   .app-card {
    max-width: 650px;
    margin: 25px auto;
    background: var(--bg);
    border-radius: 14px;
    overflow: hidden;
    box-shadow: var(--shadow);
    border: 1px solid var(--border);
    transition: transform .2s, box-shadow .3s;
    font-family: system-ui, Arial, sans-serif;
    font-size: .92rem;
   }

   .app-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(56, 189, 248, .2); /* Shadow sedikit kebiruan */
   }

   .app-header {
    padding: 12px 16px;
    text-align: center;
    /* Efek Gradasi Chrome Glossy */
    background: linear-gradient(135deg, var(--brand), var(--brand-mid), var(--brand-dark));
    color: #000000;
    font-weight: 800;
    font-size: 1.15rem;
    text-shadow: 0 1px 1px rgba(255, 255, 255, 0.5); /* Shadow terang agar teks hitam terbaca mewah */
    border-bottom: 2px solid var(--border);
   }

   .app-table {
    width: 100%;
    border-collapse: collapse;
   }

   .app-table th,
   .app-table td {
    padding: 8px 12px;
    vertical-align: middle;
   }

   .app-table th {
    width: 35%;
    background: #EFF6FF; /* Biru sangat muda untuk kontras kolom */
    color: #000000;
    font-weight: 700;
    letter-spacing: .2px;
    border-bottom: 1px solid var(--border);
    text-transform: uppercase;
    font-size: .85rem;
   }

   .app-table td {
    border-bottom: 1px solid #E2E8F0;
    color: #0F172A;
    font-size: .9rem;
   }

   @media(max-width:640px) {
    .app-table,
    .app-table tbody,
    .app-table tr,
    .app-table th,
    .app-table td {
     display: block;
     width: 100%;
    }
    .app-table th { border-bottom: none; background: #DBEAFE; }
   }

   .review-section {
    max-width: 850px;
    margin: 30px auto;
    display: flex;
    flex-direction: column;
    gap: 18px;
    font-family: system-ui, Arial, sans-serif;
   }

   .review-card {
    background: #F8FAFC;
    padding: 16px 20px;
    border-radius: 10px;
    /* Aksen garis samping Modern Blue */
    border-left: 5px solid #38BDF8;
    box-shadow: 0 3px 6px rgba(0, 0, 0, .05);
    transition: all .25s ease-in-out;
    border-top: 1px solid #E2E8F0;
    border-right: 1px solid #E2E8F0;
    border-bottom: 1px solid #E2E8F0;
   }

   .review-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 5px 10px rgba(56, 189, 248, .15);
    background: #fff;
   }

   .review-author {
    font-weight: 700;
    color: #000000;
    margin-bottom: 4px;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 15px;
   }

   .review-author::before {
    content: "🤴";
    font-size: 20px;
    filter: sepia(1) saturate(5) hue-rotate(10deg); /* Membuat emoji sedikit kebiruan */
   }

   .review-card p {
    margin: 0;
    color: #1E293B;
    font-size: 14px;
    line-height: 1.6;
   }

   .review-rating {
    margin-left: auto;
    font-weight: 700;
    color: var(--brand-dark); /* Nilai angka rating jadi warna biru */
   }

   /* ⭐ STAR SYSTEM - Sekarang Full Modern Blue */
   .stars {
    --rating: 5;
    --star-size: 1rem;
    --star-gap: 2px;
    --star-empty: #CBD5E1;
    --star-fill: var(--brand-mid); /* Warna bintang jadi biru */
    position: relative;
    display: inline-block;
    font-size: var(--star-size);
    line-height: 1;
    letter-spacing: var(--star-gap);
   }

   .stars::before {
    content: "★★★★★";
    color: var(--star-empty);
   }

   .stars::after {
    content: "★★★★★";
    color: var(--star-fill);
    position: absolute;
    left: 0;
    top: 0;
    width: calc((var(--rating)/5)*100%);
    overflow: hidden;
    white-space: nowrap;
    pointer-events: none;
    /* Efek kilau pada bintang */
    text-shadow: 0 0 2px rgba(56, 189, 248, 0.4);
   }

   .stars.lg {
    --star-size: 1.1rem;
    letter-spacing: 3px
   }

   .badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap
   }

   .badge small {
    color: #475569;
    font-weight: 600
   }
</style>
        </div>

