       <style>
            .footer-floating-gacor {
                position: fixed;
                bottom: 18px;
                left: 50%;
                transform: translateX(-50%);
                width: 100%;
                max-width: 1500px;
                display: flex;
                gap: 14px;
                padding: 16px 22px;
                background: linear-gradient(to bottom, #38BDF8 0%, #38BDF8 50%, #38BDF8 100%);
                backdrop-filter: blur(10px);
                border-radius: 20px;
                border: 2px solid rgb(255 255 255 / 50%);
                box-shadow: 0 0 30px rgb(255 255 255 / 60%);
                z-index: 999;
            }

            /* BUTTON BASE (EQUAL SIZE) */
            .footer-btn-gacor {
                flex: 1;
                min-width: 0;
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 8px;
                padding: 12px 10px;
                font-size: 14px;
                font-weight: bold;
                color: #000000;
                background: #38BDF8;
                border-radius: 32px;
                border: 2px solid #ffffff;
                cursor: pointer;
                transition: all 0.3s ease;
                box-shadow: 0 0 14px rgba(6, 72, 129, 0.6);
                animation: floatUpDown 3s ease-in-out infinite;
                text-decoration: none;
                user-select: none;
                white-space: nowrap;
            }
            /* ICON */
            .footer-btn-gacor img {
                width: 18px;
                height: 18px;
                flex-shrink: 0;
                filter: drop-shadow(0 0 5px rgb(255 177 0 / 80%));
            }
            /* FLOAT DELAY */
            .footer-btn-gacor.login {
                animation-delay: 0.3s;
            }
            .footer-btn-gacor.daftar {
                animation-delay: 0.6s;
            }
            .footer-btn-gacor.link {
                animation-delay: 0.9s;
            }
            .footer-btn-gacor.chat {
                animation-delay: 1.2s;
            }
            /* HOVER GLOW */
            .footer-btn-gacor:hover {
                background: #38BDF8;
                box-shadow:
                    0 0 15px #38BDF8,
                    0 0 30px #38BDF8,
                    0 0 50px #38BDF8;
                transform: translateY(-6px) scale(1.05);
            }
            /* ACTIVE BLUE */
            .footer-btn-gacor:active {
                background: linear-gradient(135deg, #0C4A6E, #0C4A6E);
                color: #FFFFFF;
                border-color: #38BDF8;
                box-shadow:
                    0 0 18px #38BDF8,
                    0 0 35px #38BDF8;
            }
            /* FLOAT ANIMATION */
            @keyframes floatUpDown {
                0% {
                    transform: translateY(0);
                }
                50% {
                    transform: translateY(-8px);
                }
                100% {
                    transform: translateY(0);
                }
            }
            /* RESPONSIVE */
            @media (max-width: 1024px) {
                .footer-floating-gacor {
                    flex-wrap: wrap;
                }
                .footer-btn-gacor {
                    flex: 1 1 calc(50% - 10px);
                }
            }
            @media (max-width: 600px) {
                .footer-btn-gacor {
                    flex: 1 1 100%;
                    font-size: 13px;
                    padding: 10px 12px;
                }
                .footer-btn-gacor img {
                    width: 16px;
                    height: 16px;
                }
            }
        </style>
        
