<style>
.side-banner{
    position:fixed;
    top:50%;
    transform:translateY(-50%);
    z-index:9999;
}

.left-banner{
    left:15px;
}

.right-banner{
    right:15px;
}

.side-banner img{
    width:950px;
    max-width:950px;
    height:auto;
    animation:float 2.5s ease-in-out infinite;
}

.right-banner img{
    animation:floatMirror 2.5s ease-in-out infinite;
}

@keyframes float{
    0%{transform:translateY(0);}
    50%{transform:translateY(-15px);}
    100%{transform:translateY(0);}
}

@keyframes floatMirror{
    0%{
        transform:scaleX(-1) translateY(0);
    }
    50%{
        transform:scaleX(-1) translateY(-15px);
    }
    100%{
        transform:scaleX(-1) translateY(0);
    }
}

@media (max-width:768px){
    .side-banner{
        display:none;
    }
}
  .right-banner img{
    animation: floatMirror 2.5s ease-in-out infinite;
}

@keyframes floatMirror{
    0%{
        transform:scaleX(-1) translateY(0);
    }
    50%{
        transform:scaleX(-1) translateY(-15px);
    }
    100%{
        transform:scaleX(-1) translateY(0);
    }
}
</style>

